"use client";

import React, { useState } from "react";
import { Check, Loader2 } from "lucide-react";
import { cn } from "@/lib/utils";

export interface MorphStatusButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  idleLabel?: string;
  loadingLabel?: string;
  successLabel?: string;
}

export function MorphStatusButton({
  idleLabel = "Submit Action",
  loadingLabel = "Processing",
  successLabel = "Success!",
  className,
  ...props
}: MorphStatusButtonProps) {
  const [status, setStatus] = useState<"idle" | "loading" | "success">("idle");

  const handleClick = (e: React.MouseEvent<HTMLButtonElement>) => {
    if (status !== "idle") return;
    setStatus("loading");
    props.onClick?.(e);
    setTimeout(() => {
      setStatus("success");
      setTimeout(() => setStatus("idle"), 2000);
    }, 1500);
  };

  return (
    <button
      type="button"
      onClick={handleClick}
      className={cn(
        "relative min-w-[140px] rounded-2xl px-6 py-3 text-sm font-semibold transition-all duration-300 select-none cursor-pointer border shadow-md",
        status === "idle" && "bg-zinc-900 text-white border-zinc-800 hover:bg-zinc-800",
        status === "loading" && "bg-amber-600 text-white border-amber-500 cursor-wait",
        status === "success" && "bg-emerald-600 text-white border-emerald-500",
        className
      )}
      {...props}
    >
      <span className="flex items-center justify-center gap-2">
        {status === "idle" && <span>{idleLabel}</span>}
        {status === "loading" && (
          <>
            <Loader2 className="h-4 w-4 animate-spin" />
            <span>{loadingLabel}</span>
          </>
        )}
        {status === "success" && (
          <>
            <Check className="h-4 w-4 text-white" />
            <span>{successLabel}</span>
          </>
        )}
      </span>
    </button>
  );
}

export default MorphStatusButton;
